import csv,json,zipfile
from pathlib import Path
from build_btc_web_report import read,table
from btc_perp_bot.research.archive import canonical,sha
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-liquidity-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fc=read(RUN/'forecast-summary.json')
 assert len(s)==v['accounts']==72 and rep['all_bytes_equal'] and rep['matched_files']==121 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[]
 for n in ('LQ_INFO','LQ_RISK','LQ_ALT','LQ_PRICE','LQ_INV','LQ_TREND'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='LQ_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]])
   cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.4f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('LQ_RISK','LQ_ALT','LQ_PRICE','LQ_TREND'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 for p,lags in fc.items():
  for lag,models in lags.items():
   for n,x in models.items():forecast.append([p,lag,n,x['n'],f"{x['mse']:.9f}",f"{x['sign_accuracy']*100:.2f}",x['nonpositive_liquidity_beta_weeks'] if x['nonpositive_liquidity_beta_weeks'] is not None else '해당 없음'])
 evidence={'build':'1003l1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development; completed hourly CS/AR proxies beyond price and realized risk, not actual spreads or pure liquidity. Positive compensation slope required for INFO/ALT trades. Current archive vintage, not first releases or unused OOS. No accepted strategy','references':['https://doi.org/10.1016/j.jbankfin.2020.106041','https://doi.org/10.1186/s40854-023-00598-9','https://doi.org/10.1002/ijfe.2431']}
 (DOWN/'btc-liquidity-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-liquidity-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-liquidity-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_liquidity_study.py','test_btc_liquidity_study.py','verify_btc_liquidity_study.py','reproduce_btc_liquidity_study.py','audit_btc_liquidity_data.py','collect_btc_liquidity_data.py','btc_target_ledger.py'):files.append((ROOT/'tools'/n,'source/'+n))
  folder=ROOT/'data/btc-liquidity-20261003'
  for p in sorted(folder.rglob('*')):
   if p.is_file():files.append((p,'input/'+str(p.relative_to(folder))))
  for n in ('daily.json','independent-audit.json','prepare-audit.json'):files.append((ROOT/'data/btc-cashflow-20261003'/n,'input/reused-spot/'+n))
  files.extend([(ROOT/'data/btc-venue-20261003/masks.json','input/btc-no-trade-mask.json'),(DOC/'EXPERIMENT_BTC_LIQUIDITY_20261003.md','source/EXPERIMENT_BTC_LIQUIDITY_20261003.md')])
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,3,0,0,0)),"""BTC source: previously frozen public Binance BTCUSDT hourly OHLC archives, canonical common market SHA9909be60d1d4db6b47f766de26894de9cbb55222530f9c3bbdbc19ef0899faa4. Reused daily spot-quality mask retains 16 invalid days; 3 no-trade hours remain excluded. Current archives are not historical first-release vintages. Daily CS/AR are our range-based transformations, NOT observed bid/ask spreads; 24 open-close squared log returns define daily RV. No execution-cost reduction.
Included: all 72 accounts, 35-day/nonoverlap7-prior28 features, forecasts, independent quantities/accounts and replay hashes; new daily aggregates and Decimal raw-OHLC audit; previous daily spot-quality material, no-trade mask, and experiment/source/test/verify/replay tools. Original raw BTC ZIPs/checksums, normalized common market, repository layout and common Python dependencies remain separate. This is not a standalone full environment. No individual trades, addresses/wallets, paper PDFs, secrets or live-service inputs.
Method sources: Brauneis et al. (2021), How to measure the liquidity of cryptocurrency markets?, https://doi.org/10.1016/j.jbankfin.2020.106041 ; Ahmed (2024), On the robust drivers of cryptocurrency liquidity: the case of Bitcoin, https://doi.org/10.1186/s40854-023-00598-9 . Neither authors nor data provider endorse this implementation or results. The prior cross-sectional risk-premium literature is not a demonstrated BTC timing strategy.
""")
 html='<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'self\';script-src \'none\';style-src \'self\';img-src \'self\' data:;connect-src \'none\';object-src \'none\';base-uri \'none\';form-action \'none\'"><title>BTC 유동성 보상 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1003l1</p><h1>유동성 악화의 보상 가설도<br>비용 이후 기준을 통과하지 못했습니다.</h1><p class="lead">완료된 BTC 가격범위로 유동성 변화를 측정하고 가격·실현위험과 분리했습니다. 기본 주기간은 추세 대조에 못 미쳤고, 최근에는 기대한 보상 부호가 대부분 반대여서 새 규칙이 발동하지 않았습니다.</p><div class="facts"><article><b>72</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>LQ_INFO 기본 후보</span></article><article><b>121</b><span>파일 소켓차단 바이트 일치</span></article></div><p class="boundary">2022–2025와2026.01–08은 이미 본 개발 자료입니다. CS/AR는 실제 호가나 시장깊이가 아닌 가격범위 대용치입니다. 새 OOS·인과효과·실거래 스프레드 복원이 아닙니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT. 수익·최대낙폭(DD)은 %. TREND는 저장된 E_SPOT와 일별·주요회계가 같습니다.</p>{{BASE}}<p>기본 주 +35.01%·DD16.60%·연변동성15.63%·Sharpe0.558, 최근 +0.89%·DD1.68%. 주 수익52.838713%·DD13.561952%·변동성13.343621%·Sharpe0.8과 최근 수익4.628391%의 기준을 유지했습니다. 2022년 −1.66%,2025년 −3.95%로 양수 연도도2개뿐이었습니다.</p><p>RISK·PRICE보다 나은 계좌만 보고 성공으로 부르지 않았습니다. ALT/INV의 유리한 조건이나 음의 유동성 계수를 사후 기본으로 채택하지 않습니다.</p></section><section><h2>실제 거래비용과 다른 유동성 대용치</h2><p>Corwin–Schultz(CS)는 인접 두 완료봉 high/low, Abdi–Ranaldo(AR)는 첫봉close와 두 봉의 high/low 중간값을 씁니다. 매일 정확24개1h봉에서 당일 안의23쌍만 계산했습니다. 둘째 봉이 끝나기 전에 쓸 수 없습니다.</p><p>최근7일 평균과 그 앞28일 평균의 log1p(bp) 차이로 유동성 악화를 나타냈습니다. 가격7/28일 변화와24시간 open→close 수익제곱합의1/7/28일 로그 평균을 함께 통제했습니다. 이 통제로 실제 스프레드나 순수 유동성이 식별되지는 않습니다.</p><p>2021 원문은 CS/AR의 같은 구간 유동성 변화 설명력과 비용수준 편향을 함께 보고합니다. 2024 원문의 동시 변동성 효과·전체 EBA도 선행 순익은 아닙니다. 별도 위험보상 논문 초록은 코인 간 횡단면과 달리 주요 코인 시계열 관계가 유의하지 않았다는 반증을 줍니다. 문헌 복제나 확정된 보상이 아닙니다.</p><p>유동성 지표로 원장의 수수료·impact를 낮추지 않았습니다. 개인체결·주소·지갑·실제 계좌를 조회하지 않았고 다른 자산을 거래하지 않았습니다.</p></section><section><h2>완료 시각과 무효일을 보존했습니다</h2><p>기존 BTC 시세만 재사용해2,435일 중2,419일을 유효로 두었습니다. 기존16무효일·3무거래시간과 정확한 봉 종료시각을 유지했으며,35일 중 하나라도 무효이면 모든 모형이 같은 행을 제외합니다. 보간·80%관측 허용·얇은시장의 가격대체는 하지 않았습니다.</p><p>월요일 T00UTC에 최신 D=T−1일 자료,실행은 T+1h입니다. 추가7일 자료지연도 보존했습니다. 봉이 완료됐다는 사실과 당시 아카이브 파일이 배포됐다는 사실은 다르며,현재 빈티지가 과거 첫 게시를 증명하지 않습니다.</p><p>초기 검산은2020-12-21 원시 오류봉이 정규화에서 제외돼 진단명이 다른 점을 검출했습니다. 원시에는 잘못된 종료시각/무거래,정규화에는 missing으로 남지만 양쪽 모두 같은 날 무효입니다. 원시·정규화 진단을 각각 확인하고 차이를 기록했으며 입력·마스크는 변경하지 않았습니다.</p></section><section><h2>보상 부호와 추가 예측력</h2><p>104달력주 안의 최소52공통유효주,완료된 다음7일 목표와 최근1주 분리,달력1주 HAC를 고정했습니다. INFO=가격2+위험3+CS, RISK=가격2+위험3, ALT=같은 통제+AR, PRICE=가격2. 모두 같은 행에서 무제약 회귀를 했지만 INFO/ALT는 유동성 계수가 양수이고 예측이 비용+SE를 넘으며 RISK 대비 추가분도 같은 방향일 때만 거래합니다.</p><p>기본 주기간 발동38주266일. 최근은243일 모두 기존 추세로 복귀했고 새 발동0일입니다. 최근 공통34주 중 INFO31주·ALT34주에서 보상 계수가0 이하였습니다. 음의 계수가 나타났다는 이유로 사전 양의 보상 가설을 바꾸지 않았습니다.</p><p>공통 예측194/34주. 주 MSE INFO0.005320608033 vs RISK0.005320606268·PRICE0.004756110606. 최근 INFO0.004324857749 vs RISK0.004405027930·PRICE0.004307522722. 최근 RISK 대비 개선은 있지만 양기간 추가정보 조건은 충족하지 못했습니다.</p><p>INFO 비용2배 +27.52% / +0.65%, 추가1h +32.64% / +0.65%, 추가24h +6.26% / −1.35%, 자료7일 추가지연 +41.94% / +0.89%, 위험10% +15.99% / +0.53%. 최근 기본이 양수라는 사실만으로 낮은 기준수익과24h 지연 손실을 무시하지 않았습니다.</p><details><summary>예측과 보상 부호</summary>{{FORECAST}}</details><details><summary>연도별 수익</summary>{{ANNUAL}}</details><details><summary>롱숏·비용·펀딩·위험</summary>{{COST}}</details><details><summary>모든 대조군 차이의 불확실성</summary><p>14일 원형블록2,000회95%구간(%/일);7/28일은 JSON. 반복개발·모형 선택 문제를 제거하는 독립 입증이 아닙니다.</p>{{CI}}</details></section><section><h2>모든 비용·지연·위험 조건</h2><p>현물10bp/선물5bp 수수료+각1.5bp 불리한 impact, 실제 funding,수량/금액 최소치·5%p조절밴드·종료비용 포함. 위험20%/명목상한1배,비용2배·추가1/24h 실행·위험10%·자료7일 추가지연을 보존했습니다. 실제호가·부분체결·과거규정·순간청산·세금·운영비는 완전히 복원하지 못했습니다.</p><details id="matrix"><summary>72계좌 전체 보기</summary>{{MATRIX}}</details></section><section id="proof"><h2>별도 검산·차단 재현</h2><p>19합성검사 후80현물ZIP의58,408정규화OHLC·55,637쌍 CS/AR를 별도Decimal 식으로 검산했습니다. 이어329BTC ZIP·1,836정규방정식 모형·30,672일판단·9,480폐형식 수량·52,180무거래·10,164펀딩·19,681이벤트·61,344일말을 검사했습니다. 시간DD·담보·연도·노출·선정·추세항등 및180불확실성 구간 포함.</p><p>최대 계좌차2×10⁻¹¹USDT,모형차1.30×10⁻¹³. 121파일 소켓차단 바이트 일치. 사전61e7509 → 자료5b1a0d9 → 19검사·구현37f89e6 → 독립eba442c. 검산 성공은 보상 가설 성공이 아닙니다. 이전 실험 무변경 재실행 없음.</p></section><section id="downloads"><h2>검증 자료</h2><div class="downloads"><a download href="downloads/btc-liquidity-evidence.zip">72계좌·일집계·검산 ZIP ↓</a><a download href="downloads/btc-liquidity-evidence.json">전체 수치·불확실성 JSON ↓</a><a download href="downloads/btc-liquidity-summary.csv">72조건 CSV ↓</a></div><p><a href="EXPERIMENT_BTC_LIQUIDITY_20261003.md">성과 전 명세·자료 동결</a> · <a href="BTC_WEB_RESEARCH_20261002.md">원문 감사·실패 기록</a> · <a href="https://doi.org/10.1016/j.jbankfin.2020.106041">유동성 측정 원문</a> · <a href="https://doi.org/10.1186/s40854-023-00598-9">BTC 유동성 결정요인 원문</a></p><p>원자료는 공개 Binance BTC 아카이브,CS/AR/RV·정규화·모형·매매는 자체 변환이며 원저자·공급자의 보증이 아닙니다. ZIP에 새 집계·기존 일품질자료·피처·예측·전 계좌·검산을 포함합니다. 원시 시장 ZIP·공통 시장자료·원래 경로·공통 의존성은 별도입니다. 완전 독립 실행환경이 아니며 논문 PDF는 재배포하지 않습니다.</p><p>아직 만족할 전략은 없습니다. 실거래·상시모의 서비스 없이 공개 연구만 수행합니다.</p></section><footer>BUILD1003l1 · BTC-only · 실거래 없음</footer></main></body></html>'
 html=html.replace('{{BASE}}',table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results'))
